import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.BDCokyix.js";const m=JSON.parse('{"title":"Desktop Configuration Service","description":"","frontmatter":{},"headers":[],"relativePath":"development/desktop-config.md","filePath":"development/desktop-config.md","lastUpdated":1780254295000}'),c={name:"development/desktop-config.md"};function i(n,e,r,s,l,p){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="desktop-configuration-service" tabindex="-1">Desktop Configuration Service <a class="header-anchor" href="#desktop-configuration-service" aria-label="Permalink to &quot;Desktop Configuration Service&quot;">​</a></h1><p><code>@soma/desktop-config</code> is the shared stage-detection + path-normalization layer for the Soma desktop app (the Tauri V2 app at <code>desktop/desktop-app</code>).</p><p>It centralizes:</p><ul><li>stage detection (dev / staging / prod)</li><li>stage-specific data paths</li></ul><p>Package location:</p><ul><li><code>desktop/desktop-config/</code></li></ul><p>Main implementation:</p><ul><li><code>desktop/desktop-config/src/stage-config.ts</code></li></ul><h2 id="what-it-does" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What It Does&quot;">​</a></h2><p><code>StageConfigService</code> (or the <code>resolveStageConfig</code> convenience function) resolves a runtime stage and the normalized data paths that keep dev, staging, and prod installs isolated from each other. It is framework-agnostic: it depends only on <code>node:os</code> and <code>node:path</code>, with no <code>electron</code> import and no socket plumbing.</p><p>Calling <code>resolve()</code> returns a <code>StageRuntimeConfig</code>:</p><ul><li><code>stage</code> — <code>&quot;dev&quot; | &quot;staging&quot; | &quot;prod&quot;</code></li><li><code>dataDir</code> — the stage-specific data root</li><li><code>databasePath</code> — the single SQLite file inside <code>dataDir</code> (default <code>soma.db</code>)</li><li><code>logsDir</code> — <code>dataDir/logs</code></li><li><code>cacheDir</code> — <code>dataDir/cache</code></li></ul><p>It computes paths; it does not create directories or mutate any host process state.</p><h2 id="path-normalization" tabindex="-1">Path Normalization <a class="header-anchor" href="#path-normalization" aria-label="Permalink to &quot;Path Normalization&quot;">​</a></h2><p>The data root follows each platform&#39;s convention, with a <code>-&lt;stage&gt;</code> suffix for non-prod stages:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Prod root</th><th>Non-prod example</th></tr></thead><tbody><tr><td>macOS</td><td><code>~/Library/Application Support/Soma</code></td><td><code>~/Library/Application Support/Soma-dev</code></td></tr><tr><td>Linux</td><td><code>$XDG_DATA_HOME/soma</code> (falls back to <code>~/.local/share/soma</code>)</td><td><code>~/.local/share/soma-staging</code></td></tr><tr><td>Windows</td><td><code>%APPDATA%/Soma</code> (falls back to <code>~/AppData/Roaming/Soma</code>)</td><td><code>%APPDATA%/Soma-dev</code></td></tr></tbody></table><p>The macOS/Windows folder name comes from <code>appName</code> (default <code>Soma</code>); the Linux/XDG name comes from <code>unixAppName</code> (default <code>appName.toLowerCase()</code>).</p><h2 id="stage-resolution" tabindex="-1">Stage Resolution <a class="header-anchor" href="#stage-resolution" aria-label="Permalink to &quot;Stage Resolution&quot;">​</a></h2><p>The service resolves stage from, in order:</p><ol><li>an explicit environment override (<code>SOMA_STAGE</code> / <code>SOMA_CHANNEL</code> by default)</li><li>a <code>-&lt;stage&gt;</code> suffix on the packaged product name, when <code>appNameForStage</code> is supplied (e.g. <code>Soma-staging</code> → <code>staging</code>)</li><li><code>dev</code> when <code>isDev</code> is set</li><li>otherwise <code>prod</code></li></ol><p><code>normalizeStage</code> maps common aliases — <code>production</code>/<code>release</code> → <code>prod</code>, <code>development</code>/<code>debug</code> → <code>dev</code>, <code>stage</code>/<code>beta</code>/<code>canary</code> → <code>staging</code> — and any unrecognized value falls back to <code>prod</code>.</p><p>The platform, home directory, and environment can all be injected through <code>StageConfigOptions</code> (<code>platform</code>, <code>homeDir</code>, <code>env</code>) for testing.</p><h2 id="daemon-transport" tabindex="-1">Daemon transport <a class="header-anchor" href="#daemon-transport" aria-label="Permalink to &quot;Daemon transport&quot;">​</a></h2><p>The daemon and agent runtimes are embedded in the Tauri <code>src-tauri</code> host (via the <code>desktop-daemon</code> / <code>desktop-agent</code> crates) and run in-process. There is no daemon socket and no separate daemon process — historical fields like socket paths and <code>SOMA_DAEMON_SOCKET</code> / <code>SOMA_AGENTD_SOCKET</code> are gone.</p><h2 id="current-package-shape" tabindex="-1">Current Package Shape <a class="header-anchor" href="#current-package-shape" aria-label="Permalink to &quot;Current Package Shape&quot;">​</a></h2><p>The package builds with <code>tsc</code> and ships its compiled <code>dist/</code> entry:</p><ul><li><code>desktop/desktop-config/package.json</code> — <code>main</code>/<code>types</code> point at <code>dist/stage-config.{js,d.ts}</code></li><li>the source of truth is <code>src/stage-config.ts</code></li></ul>',27)])])}const g=o(c,[["render",i]]);export{m as __pageData,g as default};
